	maxlightning: { shortDesc: "Poder do golpe base. Inicia Electric Terrain.", desc: "O poder é igual ao do Max Move base. Se tiver sucesso, inicia o efeito de Electric Terrain. Não ocorre se o usuário não estiver Dynamaxado." },
