	maxrockfall: { shortDesc: "Poder do golpe base. Inicia tempestade de areia.", desc: "O poder é igual ao do Max Move base. Se tiver sucesso, inicia o efeito de Sandstorm. Não ocorre se o usuário não estiver Dynamaxado." },
	maxstarfall: { shortDesc: "Poder do golpe base. Inicia Misty Terrain.", desc: "O poder é igual ao do Max Move base. Se tiver sucesso, inicia o efeito de Misty Terrain. Não ocorre se o usuário não estiver Dynamaxado." },
	maxsteelspike: { shortDesc: "Poder do golpe base. Aliados: +1 Defesa.", desc: "O poder é igual ao do Max Move base. Se tiver sucesso, a Defesa de cada Pokémon do lado do usuário é aumentada em 1 estágio, mesmo com substituto. Não ocorre se o usuário não estiver Dynamaxado." },
