	maxwyrmwind: { shortDesc: "Poder do golpe base. Inimigos: -1 Ataque.", desc: "O poder é igual ao do Max Move base. Se tiver sucesso, o Ataque de cada Pokémon do lado inimigo é reduzido em 1 estágio, mesmo com substituto. Não ocorre se o usuário não estiver Dynamaxado." },
	meanlook: { shortDesc: "Impede o alvo de trocar.", desc: "Impede o alvo de trocar. O alvo ainda pode trocar com Shed Shell ou usando Baton Pass, Flip Turn, Parting Shot, Teleport, U-turn ou Volt Switch. O efeito termina se o usuário ou o alvo deixar o campo." },
	meditate: { shortDesc: "Aumenta o Ataque do usuário em 1.", desc: "Aumenta o Ataque do usuário em 1 estágio." },
	mefirst: { shortDesc: "Copia o golpe do alvo a 1,5x. Tem que ser mais rápido.", desc: "O usuário usa contra o alvo o golpe que este escolheu neste turno, se possível, com poder multiplicado por 1,5. Deve ser um golpe de dano (exceto vários golpes especiais). Falha se o alvo agir antes do usuário." },
	megadrain: { shortDesc: "O usuário recupera 50% do dano causado.", desc: "O usuário recupera 1/2 do PS perdido pelo alvo, arredondado para cima na metade. Com Big Root, a cura é 1,3x o normal." },
	megahorn: { shortDesc: "Sem efeito adicional.", desc: "Sem efeito adicional." },
	megakick: { shortDesc: "Sem efeito adicional.", desc: "Sem efeito adicional." },
	megapunch: { shortDesc: "Sem efeito adicional.", desc: "Sem efeito adicional." },
	memento: { shortDesc: "Baixa At. e At. Esp. do alvo em 2. Usuário desmaia.", desc: "Reduz o Ataque e o Ataque Especial do alvo em 2 estágios. O usuário desmaia, a menos que o golpe erre ou não haja alvo. Falha totalmente se atingir um substituto." },
	menacingmoonrazemaelstrom: { shortDesc: "Ignora as Habilidades dos outros Pokémon.", desc: "Este golpe e seus efeitos ignoram as Habilidades dos outros Pokémon." },
	metalburst: { shortDesc: "Se atingido, devolve 1,5x o dano.", desc: "Causa dano ao último Pokémon inimigo que atingiu o usuário com ataque físico ou especial neste turno, igual a 1,5x o PS perdido. Falha se o usuário não foi atingido por ataque inimigo neste turno." },
	metalclaw: { shortDesc: "10% de chance de aumentar o Ataque do usuário em 1.", desc: "Tem 10% de chance de aumentar o Ataque do usuário em 1 estágio." },
	metalsound: { shortDesc: "Baixa a Def. Esp. do alvo em 2.", desc: "Reduz a Defesa Especial do alvo em 2 estágios." },
	meteorassault: { shortDesc: "O usuário não pode agir no próximo turno.", desc: "Se tiver sucesso, o usuário precisa recarregar no turno seguinte e não pode escolher um golpe." },
	meteorbeam: { shortDesc: "Turno 1: +1 At. Esp. e carrega. Turno 2: ataca.", desc: "Este ataque carrega no primeiro turno e executa no segundo. Aumenta o Ataque Especial do usuário em 1 estágio no primeiro turno. Com Power Herb, completa em um turno." },
	meteormash: { shortDesc: "20% de chance de aumentar o Ataque do usuário em 1.", desc: "Tem 20% de chance de aumentar o Ataque do usuário em 1 estágio." },
	metronome: { shortDesc: "Escolhe um golpe aleatório.", desc: "Um golpe aleatório é selecionado para uso, exceto vários golpes especiais e de status que não podem ser chamados." },
	mightycleave: { shortDesc: "Ignora proteção sem quebrá-la.", desc: "Ignora a proteção do alvo sem quebrá-la." },
	milkdrink: { shortDesc: "Cura o usuário em 50% do PS máximo.", desc: "O usuário recupera 1/2 do seu PS máximo, arredondado para cima na metade." },
	mimic: { shortDesc: "O último golpe usado pelo alvo substitui este.", desc: "Enquanto o usuário estiver ativo, este golpe é substituído pelo último golpe usado pelo alvo, com o PP máximo daquele golpe. Falha se o alvo não agiu, se o usuário se Transformou, se já conhece o golpe, ou se for um golpe não copiável." },
	mindblown: { shortDesc: "Usuário perde 50% PS máx. Atinge adjacentes.", desc: "Tendo sucesso ou não, o usuário perde 1/2 do seu PS máximo, arredondado para cima, a menos que tenha Magic Guard. Não executa e não perde PS se houver algum Pokémon com Damp em campo." },
	mindreader: { shortDesc: "O próximo golpe do usuário não erra o alvo.", desc: "Até o fim do próximo turno, o alvo não pode evitar os golpes do usuário, mesmo no meio de um golpe de dois turnos. O efeito termina se o usuário ou o alvo deixar o campo." },
	minimize: { shortDesc: "Aumenta a evasão do usuário em 2.", desc: "Aumenta a evasão do usuário em 2 estágios. Body Slam, Dragon Rush, Flying Press, Heat Crash, Heavy Slam, Malicious Moonsault, Steamroller, Stomp e Supercell Slam não checam precisão e têm dano dobrado contra o usuário enquanto ativo." },
	miracleeye: { shortDesc: "Psychic atinge Dark. Ignora evasão.", desc: "Enquanto o alvo estiver ativo, seu estágio de evasão é ignorado nas checagens de precisão se for maior que 0, e ataques do tipo Psychic podem atingir o alvo se for do tipo Dark. Falha se o alvo já estiver afetado." },
	mirrorcoat: { shortDesc: "Se atingido por golpe especial, devolve dano dobrado.", desc: "Causa dano ao último Pokémon inimigo que atingiu o usuário com ataque especial neste turno, igual a 2x o PS perdido. Falha se o usuário não foi atingido por ataque especial inimigo neste turno." },
	mirrormove: { shortDesc: "Usa contra o alvo o último golpe dele.", desc: "O usuário usa o último golpe usado pelo alvo, contra esse alvo, se possível. Falha se o alvo não agiu ou se o golpe não pode ser copiado." },
	mirrorshot: { shortDesc: "30% de chance de baixar a precisão do alvo em 1.", desc: "Tem 30% de chance de reduzir a precisão do alvo em 1 estágio." },
	mist: { shortDesc: "5 turnos: protege o time de quedas de status.", desc: "Por 5 turnos, o usuário e seus aliados ficam protegidos contra reduções de estágios de status por outros Pokémon. Falha se o efeito já estiver ativo no lado do usuário." },
	mistball: { shortDesc: "50% de chance de baixar o At. Esp. do alvo em 1.", desc: "Tem 50% de chance de reduzir o Ataque Especial do alvo em 1 estágio." },
	mistyexplosion: { shortDesc: "Usuário desmaia. Em Misty Terrain: 1,5x poder.", desc: "Se o terreno for Misty Terrain e o usuário estiver aterrado, o poder é multiplicado por 1,5. O usuário desmaia após usar, mesmo se falhar por falta de alvo. Não executa se houver algum Pokémon com Damp em campo." },
	mistyterrain: { shortDesc: "5 turnos: sem status, -poder Dragon vs aterrados.", desc: "Por 5 turnos, o terreno vira Misty Terrain. O poder de ataques Dragon contra Pokémon aterrados é multiplicado por 0,5, e Pokémon aterrados não podem receber status não-volátil nem confusão. Falha se o terreno já for Misty Terrain." },
	moonblast: { shortDesc: "30% de chance de baixar o At. Esp. do alvo em 1.", desc: "Tem 30% de chance de reduzir o Ataque Especial do alvo em 1 estágio." },
	moongeistbeam: { shortDesc: "Ignora as Habilidades dos outros Pokémon.", desc: "Este golpe e seus efeitos ignoram as Habilidades dos outros Pokémon." },
