	naturalgift: { shortDesc: "Poder e tipo dependem da Berry do usuário.", desc: "O tipo e o poder deste golpe dependem da Berry que o usuário segura, e a Berry é perdida. Falha se o usuário não segura uma Berry, tem Klutz, ou está sob Embargo ou Magic Room." },
	naturepower: { shortDesc: "Golpe depende do terreno (padrão Tri Attack).", desc: "Este golpe chama outro golpe conforme o terreno: Tri Attack no terreno normal, Thunderbolt em Electric Terrain, Moonblast em Misty Terrain, Energy Ball em Grassy Terrain e Psychic em Psychic Terrain." },
	naturesmadness: { shortDesc: "Causa dano igual a 1/2 do PS atual do alvo.", desc: "Causa ao alvo dano igual à metade do seu PS atual, arredondado para baixo, mas nunca menos que 1 PS." },
	needlearm: { shortDesc: "30% de chance de fazer o alvo hesitar.", desc: "Tem 30% de chance de fazer o alvo hesitar." },
	neverendingnightmare: { shortDesc: "O poder é igual ao Z-Power do golpe base.", desc: "O poder é igual ao Z-Power do golpe base." },
	nightdaze: { shortDesc: "40% de chance de baixar a precisão do alvo em 1.", desc: "Tem 40% de chance de reduzir a precisão do alvo em 1 estágio." },
	nightmare: { shortDesc: "Alvo dormindo perde 1/4 do PS máx. por turno.", desc: "Faz o alvo perder 1/4 do seu PS máximo, arredondado para baixo, ao fim de cada turno enquanto estiver dormindo. Não afeta o alvo a menos que esteja dormindo. O efeito termina quando o alvo acorda." },
	nightshade: { shortDesc: "Causa dano igual ao nível do usuário.", desc: "Causa ao alvo dano igual ao nível do usuário." },
